CREATE TABLE discovery_settings (run_id TEXT PRIMARY KEY,document TEXT NOT NULL,revision TEXT NOT NULL);
CREATE TABLE discovery_markets (run_id TEXT NOT NULL,market_id TEXT NOT NULL,attempt_count INTEGER NOT NULL DEFAULT 0,next_due_at REAL,state TEXT NOT NULL,last_attempt_at REAL,PRIMARY KEY(run_id,market_id));
CREATE TABLE discovery_attempts (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,market_id TEXT NOT NULL,ordinal INTEGER NOT NULL,source_url TEXT NOT NULL,market_document TEXT NOT NULL,state TEXT NOT NULL,reservation_id TEXT,result TEXT NOT NULL DEFAULT '{}',created_at REAL NOT NULL,completed_at REAL,UNIQUE(run_id,market_id,ordinal));
CREATE TABLE discovery_allocations (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,entity_id TEXT NOT NULL UNIQUE,amount_micro_usd INTEGER NOT NULL CHECK(amount_micro_usd>=0),created_at REAL NOT NULL);
CREATE INDEX discovery_allocations_run ON discovery_allocations(run_id);
CREATE TABLE discoveries (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,market_id TEXT NOT NULL,opportunity_id TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,observed_need TEXT NOT NULL,proposed_offering TEXT NOT NULL,evidence TEXT NOT NULL,capabilities TEXT NOT NULL,estimated_cost_micro_usd INTEGER,uncertainty TEXT NOT NULL,next_action TEXT NOT NULL,created_at REAL NOT NULL,last_seen_at REAL NOT NULL,expires_at REAL NOT NULL);
CREATE TABLE discovery_observations (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,discovery_id TEXT NOT NULL REFERENCES discoveries(id),attempt_id TEXT NOT NULL REFERENCES discovery_attempts(id),evidence TEXT NOT NULL,observed_at REAL NOT NULL,UNIQUE(discovery_id,attempt_id));
CREATE TABLE discovery_experiments (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,opportunity_id TEXT NOT NULL UNIQUE REFERENCES opportunities(id),request_id TEXT NOT NULL,fingerprint TEXT NOT NULL,hypothesis TEXT NOT NULL,allowance_micro_usd INTEGER NOT NULL,deadline REAL NOT NULL,success_criteria TEXT NOT NULL,stop_conditions TEXT NOT NULL,plan TEXT NOT NULL,state TEXT NOT NULL,reservation_id TEXT,artifact TEXT,result TEXT NOT NULL DEFAULT '{}',created_at REAL NOT NULL,completed_at REAL,UNIQUE(run_id,request_id));
CREATE INDEX discovery_experiments_due ON discovery_experiments(run_id,state,deadline);
CREATE TABLE discovery_experiment_orders (run_id TEXT NOT NULL,experiment_id TEXT NOT NULL REFERENCES discovery_experiments(id),order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),evidence_reference TEXT NOT NULL,created_at REAL NOT NULL,PRIMARY KEY(experiment_id,order_id));
CREATE TABLE discovery_outcomes (id TEXT PRIMARY KEY,run_id TEXT NOT NULL,market_id TEXT NOT NULL,entity_id TEXT NOT NULL,kind TEXT NOT NULL,document TEXT NOT NULL,observed_at REAL NOT NULL,UNIQUE(run_id,entity_id,kind));
CREATE TABLE discovery_observation_cursors (run_id TEXT NOT NULL,kind TEXT NOT NULL,cursor TEXT NOT NULL,PRIMARY KEY(run_id,kind));
